const TOOL_NAME = 'text_transform';
const MODES = ['uppercase', 'lowercase', 'slug'];

function slugify(input) {
  const hyphenated = String(input).toLowerCase().replace(/[^a-z0-9]+/g, '-');
  return hyphenated.replace(/^-+|-+$/g, '');
}

export async function listTools() {
  return [
    {
      name: TOOL_NAME,
      description: 'Transform text: uppercase, lowercase, or URL-friendly slug.',
      inputSchema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          text: {
            type: 'string',
            description: 'Input text to transform.',
          },
          mode: {
            type: 'string',
            enum: MODES,
            description: 'Transformation mode.',
          },
          trim: {
            type: 'boolean',
            description: 'Trim leading/trailing whitespace before transforming. Defaults to true.',
          },
        },
        required: ['text', 'mode'],
      },
    },
  ];
}

export async function callTool(name, args) {
  if (name !== TOOL_NAME) {
    throw new Error(`Unknown tool: ${name}`);
  }

  const params = args && typeof args === 'object' ? args : {};

  const allowed = new Set(['text', 'mode', 'trim']);
  for (const key of Object.keys(params)) {
    if (!allowed.has(key)) {
      throw new Error(`Unknown argument: ${key}`);
    }
  }

  if (!('text' in params)) {
    throw new Error('Missing required argument: text');
  }
  if (typeof params.text !== 'string') {
    throw new Error('Invalid argument: text must be a string');
  }

  if (!('mode' in params)) {
    throw new Error('Missing required argument: mode');
  }
  if (typeof params.mode !== 'string') {
    throw new Error('Invalid argument: mode must be a string');
  }
  if (!MODES.includes(params.mode)) {
    throw new Error(`Invalid argument: mode must be one of ${MODES.join(', ')}`);
  }

  let trim = true;
  if ('trim' in params) {
    if (typeof params.trim !== 'boolean') {
      throw new Error('Invalid argument: trim must be a boolean');
    }
    trim = params.trim;
  }

  let value = params.text;
  if (trim) value = value.trim();

  switch (params.mode) {
    case 'uppercase':
      value = value.toUpperCase();
      break;
    case 'lowercase':
      value = value.toLowerCase();
      break;
    case 'slug':
      value = slugify(value);
      break;
  }

  return { content: [{ type: 'text', text: value }] };
}

